// Lossless 079 transport reuses unchanged, hash-verified 078 offer/budget pools.
export function hydrateSimulator079(d,base){if(base.version!=='simulator-078-002')throw Error('079 requires the frozen final 078 baseline');const byId=new Map(base.rows.map(r=>[r.id,r]));return{...d,catalog:{...base.catalog,...d.catalogAdditions},budgets:[...base.budgets,...d.budgetAdditions],rows:d.rows.map(r=>{const before=byId.get(r.id);if(!before||before.cohort!==r.cohort)throw Error('079 baseline model/cohort mismatch');return{...r,before:before.after,pool:[...before.pool,...r.poolAppend]};})};}
